import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { runFfmpeg, runFfprobe } from "../src/index.js";

for (const run of [runFfmpeg, runFfprobe]) {
  // oxlint-disable-next-line no-await-in-loop -- Keep large output fixtures sequential.
  await test(`${run.name} preserves stdout and stderr before exit`, async () => {
    const distDir = mkdtempSync(join(tmpdir(), "ffmpeg-wasm-output-"));
    const line = "x".repeat(4 * 1024 * 1024);
    try {
      for (const tool of ["ffmpeg", "ffprobe"]) {
        writeFileSync(
          join(distDir, `${tool}.js`),
          `export default async function(options) {
            const line = "x".repeat(${line.length});
            options.print(line);
            options.printErr(line);
            options.onExit(7);
            return {};
          }`,
        );
        writeFileSync(join(distDir, `${tool}_g.wasm`), "");
      }
      const result = await run([], { distDir, timeoutMs: 5000 });
      assert.equal(result.exitCode, 7);
      assert.equal(result.stdout.length, line.length + 1, "stdout was truncated");
      assert.equal(result.stderr.length, line.length + 1, "stderr was truncated");
      assert.equal(result.stdoutText, `${line}\n`);
      assert.equal(result.stderrText, `${line}\n`);
    } finally {
      rmSync(distDir, { recursive: true, force: true });
    }
  });
}

await test("runner preserves large NODERAWFS-style descriptor writes", async () => {
  const distDir = mkdtempSync(join(tmpdir(), "ffmpeg-wasm-raw-output-"));
  const bytes = Buffer.alloc(4 * 1024 * 1024, 165);
  try {
    writeFileSync(
      join(distDir, "ffmpeg.js"),
      `import { writeSync } from "node:fs";
      export default async function(options) {
        const bytes = Buffer.alloc(${bytes.length}, 165);
        writeSync(1, bytes);
        writeSync(2, bytes);
        options.onExit(0);
        return {};
      }`,
    );
    writeFileSync(join(distDir, "ffmpeg_g.wasm"), "");
    const result = await runFfmpeg([], { distDir, timeoutMs: 5000 });
    assert.equal(result.exitCode, 0);
    assert.equal(result.stdout.length, bytes.length, "raw stdout was truncated");
    assert.equal(result.stderr.length, bytes.length, "raw stderr was truncated");
    assert.deepEqual(result.stdout, bytes);
    assert.deepEqual(result.stderr, bytes);
  } finally {
    rmSync(distDir, { recursive: true, force: true });
  }
});

await test("runner preserves diagnostics when the module fails", async () => {
  const distDir = mkdtempSync(join(tmpdir(), "ffmpeg-wasm-output-error-"));
  const message = "failure".repeat(1024 * 1024);
  try {
    writeFileSync(
      join(distDir, "ffmpeg.js"),
      `export default async function() { throw "failure".repeat(${1024 * 1024}); }`,
    );
    writeFileSync(join(distDir, "ffmpeg_g.wasm"), "");
    const result = await runFfmpeg([], { distDir, timeoutMs: 5000 });
    assert.equal(result.exitCode, 1);
    assert.equal(result.stderr.length, message.length + 1, "diagnostic was truncated");
    assert.equal(result.stderrText, `${message}\n`);
  } finally {
    rmSync(distDir, { recursive: true, force: true });
  }
});

import assert from "node:assert/strict";
import { test } from "node:test";
import {
  isCurrentSource,
  resultForCurrentSource,
  statusForRenderProgress,
} from "../playground/current-source.js";

await test("resultForCurrentSource drops a render after the source file changes", () => {
  const original = new File(["one"], "clip.webm", { type: "video/webm" });
  const replacement = new File(["one"], "clip.webm", { type: "video/webm" });
  const rendered = { bytes: 4, name: "clip.mp4" };
  assert.equal(isCurrentSource(original, original), true);
  assert.equal(isCurrentSource(original, replacement), false);
  assert.equal(isCurrentSource(original, null), false);
  assert.deepEqual(resultForCurrentSource(original, original, rendered), rendered);
  assert.equal(resultForCurrentSource(original, replacement, rendered), null);
  assert.equal(resultForCurrentSource(original, null, rendered), null);
});

await test("stale render progress does not mark the replacement busy", () => {
  const original = new File(["one"], "clip.webm", { type: "video/webm" });
  const replacement = new File(["two"], "other.mov", { type: "video/quicktime" });
  assert.equal(statusForRenderProgress(original, replacement, { phase: "end" }, 4), null);
  assert.equal(
    statusForRenderProgress(replacement, replacement, { phase: "end" }, 4),
    "Rendering 100%",
  );
  assert.equal(
    statusForRenderProgress(replacement, replacement, { outTimeSeconds: 1 }, 4),
    "Rendering 25%",
  );
});

await test("resultForCurrentSource drops a probe after the source file changes", () => {
  const original = new File(["one"], "clip.webm", { type: "video/webm" });
  const replacement = new File(["two"], "other.mov", { type: "video/quicktime" });
  const probe = { streams: [{ codec_type: "video" }] };
  assert.equal(isCurrentSource(original, replacement), false);
  assert.deepEqual(resultForCurrentSource(original, original, probe), probe);
  assert.equal(resultForCurrentSource(original, replacement, probe), null);
});

import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { test } from "node:test";
import { fileURLToPath, pathToFileURL } from "node:url";
import { endChildStdin } from "../src/end-stdin.js";

await test("endChildStdin writes a payload that the child can read", async () => {
  const payload = Buffer.from("hello-stdin");
  const child = spawn(
    process.execPath,
    [
      "-e",
      `
        let n = 0;
        process.stdin.on("data", (chunk) => {
          n += chunk.length;
        });
        process.stdin.on("end", () => {
          process.stdout.write(String(n));
        });
      `,
    ],
    { stdio: ["pipe", "pipe", "pipe"] },
  );

  const stdinErrors: Error[] = [];
  endChildStdin(child.stdin, payload, collectStdinError(stdinErrors));

  const [stdout, status] = await Promise.all([
    readAll(child.stdout),
    new Promise<number | null>((resolve, reject) => {
      child.once("error", reject);
      child.once("close", (code) => {
        resolve(code);
      });
    }),
  ]);

  assert.deepEqual(stdinErrors, []);
  assert.equal(status, 0);
  assert.equal(stdout.toString("utf8"), String(payload.length));
});

await test("writing stdin after the child has closed does not become an uncaughtException", () => {
  const helperHref = pathToFileURL(
    fileURLToPath(new URL("../src/end-stdin.js", import.meta.url)),
  ).href;
  const source = `
import { spawn } from "node:child_process";
import { endChildStdin } from ${JSON.stringify(helperHref)};

const child = spawn(process.execPath, ["-e", "process.exit(0)"], {
  stdio: ["pipe", "ignore", "ignore"],
});
endChildStdin(child.stdin, Buffer.alloc(10 * 1024 * 1024), () => {});
await new Promise((resolve, reject) => {
  child.once("error", reject);
  child.once("close", resolve);
});
await new Promise((resolve) => {
  setTimeout(resolve, 100);
});
`;
  const result = spawnSync(process.execPath, ["--input-type=module", "--eval", source], {
    encoding: "utf8",
  });
  assert.equal(
    result.status,
    0,
    `expected child to exit 0 without uncaughtException, got ${String(result.status)}\n${result.stderr}`,
  );
});

function collectStdinError(errors: Error[]): (error: Error) => void {
  return (error: Error) => {
    errors.push(error);
  };
}

async function readAll(stream: NodeJS.ReadableStream | null): Promise<Buffer> {
  if (!stream) {
    return Buffer.alloc(0);
  }
  const chunks: Buffer[] = [];
  for await (const chunk of stream) {
    chunks.push(Buffer.from(chunk));
  }
  return Buffer.concat(chunks);
}

import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
